-- inspection export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from inspections i cross join bounds where i.organization_id = $5 and i.deleted_at is null and i.is_wet = $6 and i.density = any($7::larval_density[]) and coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) and i.habitat_type_id = any($8::uuid[]) and i.inspected_by_profile_id = any($9::uuid[]) and i.inspection_date >= $10 and i.inspection_date <= $11 and exists ( select 1 from regions rf where rf.id = any($12::uuid[]) and rf.organization_id = i.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select i.inspection_date::text as "c0", h.habitat_name as "c1", ht.name as "c2", a.display_name as "c3", p.display_name as "c4", case i.is_wet when true then 'Yes' when false then 'No' end as "c5", i.dip_count as "c6", (upper(left(replace(i.density::text, '_', ' '), 1)) || substr(replace(i.density::text, '_', ' '), 2)) as "c7", i.larvae_count as "c8", case i.has_eggs when true then 'Yes' when false then 'No' end as "c9", case i.has_first_instar when true then 'Yes' when false then 'No' end as "c10", case i.has_second_instar when true then 'Yes' when false then 'No' end as "c11", case i.has_third_instar when true then 'Yes' when false then 'No' end as "c12", case i.has_fourth_instar when true then 'Yes' when false then 'No' end as "c13", case i.has_pupae when true then 'Yes' when false then 'No' end as "c14", case coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) when true then 'Yes' when false then 'No' end as "c15", i.lat as "c16", i.lng as "c17", to_char(i.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c18", to_char(i.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c19" from inspections i left join habitats h on h.id = i.habitat_id left join addresses a on a.id = i.address_id left join profiles p on p.id = i.inspected_by_profile_id left join habitat_types ht on ht.id = i.habitat_type_id cross join bounds where i.organization_id = $7 and i.deleted_at is null and i.is_wet = $8 and i.density = any($9::larval_density[]) and coalesce( i.is_wet and (i.density <> 'none' or i.larvae_count > 0), false ) and i.habitat_type_id = any($10::uuid[]) and i.inspected_by_profile_id = any($11::uuid[]) and i.inspection_date >= $12 and i.inspection_date <= $13 and exists ( select 1 from regions rf where rf.id = any($14::uuid[]) and rf.organization_id = i.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326) order by i.inspection_date desc, i.created_at desc, i.id limit $15

-- habitat export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from habitats h cross join bounds where h.organization_id = $5 and h.deleted_at is null and ( h.is_active = true and h.id in ( select latest.habitat_id from ( select distinct on (i.habitat_id) i.id, i.habitat_id, i.inspection_date, i.density from inspections i where i.organization_id = $6 and i.deleted_at is null and i.habitat_id is not null and i.inspection_date > ((now()) at time zone 'America/New_York')::date - $7::int order by i.habitat_id, i.inspection_date desc, i.created_at desc ) latest where latest.inspection_date <= ((now()) at time zone 'America/New_York')::date and latest.density = any($8::larval_density[]) and not exists ( select 1 from applications a where a.organization_id = $9 and a.deleted_at is null and a.application_date >= latest.inspection_date and (a.habitat_id = latest.habitat_id or a.inspection_id = latest.id) ) and not exists ( select 1 from source_reductions sr where sr.organization_id = $10 and sr.deleted_at is null and sr.source_reduction_date >= latest.inspection_date and (sr.habitat_id = latest.habitat_id or sr.inspection_id = latest.id) ) and not exists ( select 1 from biocontrol_actions b where b.organization_id = $11 and b.deleted_at is null and b.biocontrol_date >= latest.inspection_date and (b.habitat_id = latest.habitat_id or b.inspection_id = latest.id) ) and not exists ( select 1 from requested_control_actions rca where rca.organization_id = $12 and rca.deleted_at is null and rca.resolved_at is null and rca.habitat_id = latest.habitat_id ) ) ) and h.is_active = $13 and h.habitat_type_id = any($14::uuid[]) and exists ( select 1 from tag_items ti where ti.entity_type = 'habitat' and ti.entity_id = h.id and ti.deleted_at is null and ti.tag_id = any($15::uuid[]) ) and exists ( select 1 from regions rf where rf.id = any($16::uuid[]) and rf.organization_id = h.organization_id and rf.deleted_at is null and rf.geom && h.geom and case when h.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(h.geom) then h.geom else st_collectionextract(st_makevalid(h.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, h.geom) end ) and ( position(lower($17) in lower(coalesce(h.habitat_name, ''))) > 0 or position(lower($18) in lower(h.description)) > 0 ) and h.geom && bounds.geom_4326 and st_intersects(h.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select h.habitat_name as "c0", ht.name as "c1", ad.display_name as "c2", h.description as "c3", case h.is_active when true then 'Yes' when false then 'No' end as "c4", case h.is_inaccessible when true then 'Yes' when false then 'No' end as "c5", ( select string_agg(tg.tag_name, ', ' order by tg.tag_name) from tag_items ti join tags tg on tg.id = ti.tag_id where ti.entity_type = 'habitat' and ti.entity_id = h.id and ti.deleted_at is null and tg.deleted_at is null ) as "c6", h.lat as "c7", h.lng as "c8", to_char(h.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c9", to_char(h.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c10" from habitats h left join habitat_types ht on ht.id = h.habitat_type_id left join addresses ad on ad.id = h.address_id cross join bounds where h.organization_id = $7 and h.deleted_at is null and ( h.is_active = true and h.id in ( select latest.habitat_id from ( select distinct on (i.habitat_id) i.id, i.habitat_id, i.inspection_date, i.density from inspections i where i.organization_id = $8 and i.deleted_at is null and i.habitat_id is not null and i.inspection_date > ((now()) at time zone 'America/New_York')::date - $9::int order by i.habitat_id, i.inspection_date desc, i.created_at desc ) latest where latest.inspection_date <= ((now()) at time zone 'America/New_York')::date and latest.density = any($10::larval_density[]) and not exists ( select 1 from applications a where a.organization_id = $11 and a.deleted_at is null and a.application_date >= latest.inspection_date and (a.habitat_id = latest.habitat_id or a.inspection_id = latest.id) ) and not exists ( select 1 from source_reductions sr where sr.organization_id = $12 and sr.deleted_at is null and sr.source_reduction_date >= latest.inspection_date and (sr.habitat_id = latest.habitat_id or sr.inspection_id = latest.id) ) and not exists ( select 1 from biocontrol_actions b where b.organization_id = $13 and b.deleted_at is null and b.biocontrol_date >= latest.inspection_date and (b.habitat_id = latest.habitat_id or b.inspection_id = latest.id) ) and not exists ( select 1 from requested_control_actions rca where rca.organization_id = $14 and rca.deleted_at is null and rca.resolved_at is null and rca.habitat_id = latest.habitat_id ) ) ) and h.is_active = $15 and h.habitat_type_id = any($16::uuid[]) and exists ( select 1 from tag_items ti where ti.entity_type = 'habitat' and ti.entity_id = h.id and ti.deleted_at is null and ti.tag_id = any($17::uuid[]) ) and exists ( select 1 from regions rf where rf.id = any($18::uuid[]) and rf.organization_id = h.organization_id and rf.deleted_at is null and rf.geom && h.geom and case when h.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(h.geom) then h.geom else st_collectionextract(st_makevalid(h.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, h.geom) end ) and ( position(lower($19) in lower(coalesce(h.habitat_name, ''))) > 0 or position(lower($20) in lower(h.description)) > 0 ) and h.geom && bounds.geom_4326 and st_intersects(h.geom, bounds.geom_4326) order by coalesce(h.habitat_name, h.id::text) collate natural_sort, h.id limit $21

-- sample export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from samples s join inspections i on i.id = s.inspection_id cross join bounds where s.organization_id = $5 and s.deleted_at is null and i.deleted_at is null and i.geom is not null and i.inspection_date >= $6 and i.inspection_date <= $7 and s.has_non_mosquito = true and exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null and ss.species_id = any($8::uuid[]) ) and ( s.is_zero_larvae = false and s.unidentifiable_reason is null and i.deleted_at is null and not exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null ) ) and exists ( select 1 from regions rf where rf.id = any($9::uuid[]) and rf.organization_id = s.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select s.display_name as "c0", i.inspection_date::text as "c1", h.habitat_name as "c2", a.display_name as "c3", (upper(left(replace(( case when exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null ) then 'identified' when s.is_zero_larvae then 'zero_larvae' when s.unidentifiable_reason is not null then 'unidentifiable' else 'awaiting' end )::text, '_', ' '), 1)) || substr(replace(( case when exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null ) then 'identified' when s.is_zero_larvae then 'zero_larvae' when s.unidentifiable_reason is not null then 'unidentifiable' else 'awaiting' end )::text, '_', ' '), 2)) as "c4", named.species as "c5", coalesce(agg.larvae_total, 0)::int as "c6", agg.identified_at as "c7", case s.is_zero_larvae when true then 'Yes' when false then 'No' end as "c8", case s.has_non_mosquito when true then 'Yes' when false then 'No' end as "c9", s.unidentifiable_reason as "c10", sp_by.display_name as "c11", i.lat as "c12", i.lng as "c13", to_char(s.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c14", to_char(s.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c15" from samples s join inspections i on i.id = s.inspection_id left join habitats h on h.id = i.habitat_id left join addresses a on a.id = i.address_id left join lateral ( select max(ss.identified_at)::text as identified_at, sum(ss.larvae_count)::int as larvae_total, json_agg( json_build_object('speciesId', ss.species_id, 'larvaeCount', ss.larvae_count) order by ss.larvae_count desc, ss.species_id ) as results from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null ) agg on true left join profiles sp_by on sp_by.id = s.created_by_profile_id left join lateral ( select string_agg( sp.display_name || ' (' || ss.larvae_count || ')', '; ' order by ss.larvae_count desc, sp.display_name ) as species from sample_species ss join species sp on sp.id = ss.species_id where ss.sample_id = s.id and ss.deleted_at is null ) named on true cross join bounds where s.organization_id = $7 and s.deleted_at is null and i.deleted_at is null and i.geom is not null and i.inspection_date >= $8 and i.inspection_date <= $9 and s.has_non_mosquito = true and exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null and ss.species_id = any($10::uuid[]) ) and ( s.is_zero_larvae = false and s.unidentifiable_reason is null and i.deleted_at is null and not exists ( select 1 from sample_species ss where ss.sample_id = s.id and ss.deleted_at is null ) ) and exists ( select 1 from regions rf where rf.id = any($11::uuid[]) and rf.organization_id = s.organization_id and rf.deleted_at is null and rf.geom && i.geom and case when i.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(i.geom) then i.geom else st_collectionextract(st_makevalid(i.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, i.geom) end ) and i.geom && bounds.geom_4326 and st_intersects(i.geom, bounds.geom_4326) order by i.inspection_date desc, s.created_at desc, s.id limit $12

-- trap export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from traps t cross join bounds where t.organization_id = $5 and t.deleted_at is null and t.collection_method_id = any($6::uuid[]) and t.is_active = $7 and ( t.trap_name ilike $8 or t.trap_code ilike $9 or t.description ilike $10 ) and exists ( select 1 from regions rf where rf.id = any($11::uuid[]) and rf.organization_id = t.organization_id and rf.deleted_at is null and rf.geom && t.geom and case when t.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(t.geom) then t.geom else st_collectionextract(st_makevalid(t.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, t.geom) end ) and t.geom && bounds.geom_4326 and st_intersects(t.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select t.trap_code as "c0", t.trap_name as "c1", cm.name as "c2", cl.name as "c3", ad.display_name as "c4", t.description as "c5", case t.is_active when true then 'Yes' when false then 'No' end as "c6", t.lat as "c7", t.lng as "c8", to_char(t.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c9", to_char(t.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c10" from traps t left join collection_methods cm on cm.id = t.collection_method_id left join collection_lures cl on cl.id = t.collection_lure_id left join addresses ad on ad.id = t.address_id cross join bounds where t.organization_id = $7 and t.deleted_at is null and t.collection_method_id = any($8::uuid[]) and t.is_active = $9 and ( t.trap_name ilike $10 or t.trap_code ilike $11 or t.description ilike $12 ) and exists ( select 1 from regions rf where rf.id = any($13::uuid[]) and rf.organization_id = t.organization_id and rf.deleted_at is null and rf.geom && t.geom and case when t.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(t.geom) then t.geom else st_collectionextract(st_makevalid(t.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, t.geom) end ) and t.geom && bounds.geom_4326 and st_intersects(t.geom, bounds.geom_4326) order by coalesce(t.trap_code, t.trap_name) collate natural_sort asc nulls last, t.created_at desc, t.id limit $14

-- collection export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from collections c cross join bounds where c.organization_id = $5 and c.deleted_at is null and c.collection_method_id = any($6::uuid[]) and c.has_problem = true and ( c.is_zero_result = false and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) is not null and not exists ( select 1 from collection_species cs where cs.collection_id = c.id and cs.deleted_at is null ) ) and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) >= $7 and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) <= $8 and exists ( select 1 from regions rf where rf.id = any($9::uuid[]) and rf.organization_id = c.organization_id and rf.deleted_at is null and rf.geom && c.geom and case when c.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(c.geom) then c.geom else st_collectionextract(st_makevalid(c.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, c.geom) end ) and c.geom && bounds.geom_4326 and st_intersects(c.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select (coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date))::text as "c0", case when c.collection_timing_mode = 'exact_timestamps' then to_char(c.collected_at at time zone $5, 'YYYY-MM-DD HH24:MI') end as "c1", case when c.collection_timing_mode = 'exact_timestamps' then to_char(c.started_at at time zone $6, 'YYYY-MM-DD HH24:MI') end as "c2", case when c.collection_timing_mode = 'collection_date_duration' then c.duration_amount end as "c3", case when c.collection_timing_mode = 'collection_date_duration' then du.unit_name end as "c4", nullif(concat_ws(' - ', t.trap_code, t.trap_name), '') as "c5", a.display_name as "c6", cm.name as "c7", cl.name as "c8", set_by.display_name as "c9", collected_by.display_name as "c10", (upper(left(replace((case when c.collection_timing_mode = 'exact_timestamps' and c.collected_at is null then 'pending' when c.has_problem then 'problem' when c.is_zero_result then 'zero_result' else 'collected' end)::text, '_', ' '), 1)) || substr(replace((case when c.collection_timing_mode = 'exact_timestamps' and c.collected_at is null then 'pending' when c.has_problem then 'problem' when c.is_zero_result then 'zero_result' else 'collected' end)::text, '_', ' '), 2)) as "c11", case c.has_problem when true then 'Yes' when false then 'No' end as "c12", case c.is_zero_result when true then 'Yes' when false then 'No' end as "c13", case c.has_bycatch when true then 'Yes' when false then 'No' end as "c14", caught.species as "c15", caught.mosquitoes as "c16", c.lat as "c17", c.lng as "c18", to_char(c.created_at at time zone $7, 'YYYY-MM-DD HH24:MI') as "c19", to_char(c.updated_at at time zone $8, 'YYYY-MM-DD HH24:MI') as "c20" from collections c left join addresses a on a.id = c.address_id left join traps t on t.id = c.trap_id left join collection_methods cm on cm.id = c.collection_method_id left join collection_lures cl on cl.id = c.collection_lure_id left join units du on du.id = c.duration_unit_id left join profiles set_by on set_by.id = c.set_by_profile_id left join profiles collected_by on collected_by.id = c.collected_by_profile_id left join lateral ( select string_agg(per.entry, '; ' order by per.total desc, per.entry) as species, sum(per.total)::int as mosquitoes from ( select sp.display_name || coalesce(', ' || cs.sex::text, '') || ' (' || sum(cs.count) || ')' as entry, sum(cs.count) as total from collection_species cs join species sp on sp.id = cs.species_id where cs.collection_id = c.id and cs.deleted_at is null group by sp.display_name, cs.sex ) per ) caught on true cross join bounds where c.organization_id = $9 and c.deleted_at is null and c.collection_method_id = any($10::uuid[]) and c.has_problem = true and ( c.is_zero_result = false and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) is not null and not exists ( select 1 from collection_species cs where cs.collection_id = c.id and cs.deleted_at is null ) ) and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) >= $11 and coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) <= $12 and exists ( select 1 from regions rf where rf.id = any($13::uuid[]) and rf.organization_id = c.organization_id and rf.deleted_at is null and rf.geom && c.geom and case when c.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(c.geom) then c.geom else st_collectionextract(st_makevalid(c.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, c.geom) end ) and c.geom && bounds.geom_4326 and st_intersects(c.geom, bounds.geom_4326) order by coalesce(((c.collected_at) at time zone 'America/New_York')::date, c.collection_date) desc nulls last, c.created_at desc, c.id limit $14

-- application export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from applications a cross join bounds where a.organization_id = $5 and a.deleted_at is null and a.insecticide_id = any($6::uuid[]) and a.application_method_id = any($7::uuid[]) and a.applicator_profile_id = any($8::uuid[]) and a.application_date >= $9 and a.application_date <= $10 and exists ( select 1 from regions rf where rf.id = any($11::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and case when a.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(a.geom) then a.geom else st_collectionextract(st_makevalid(a.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, a.geom) end ) and a.geom && bounds.geom_4326 and st_intersects(a.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select a.application_date::text as "c0", ins.trade_name as "c1", ins.active_ingredient as "c2", ins.registration_number as "c3", am.name as "c4", a.amount_applied as "c5", au.unit_name as "c6", (select string_agg(batch.name, ', ') from json_array_elements_text(batches.batch_names) as batch(name)) as "c7", ap.display_name as "c8", hb.habitat_name as "c9", ad.display_name as "c10", a.lat as "c11", a.lng as "c12", to_char(a.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c13", to_char(a.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c14" from applications a left join profiles ap on ap.id = a.applicator_profile_id left join lateral ( select json_agg(ib.batch_name order by ib.batch_name) as batch_names from application_batches abx join insecticide_batches ib on ib.id = abx.insecticide_batch_id where abx.application_id = a.id and abx.deleted_at is null and ib.deleted_at is null ) batches on true left join insecticides ins on ins.id = a.insecticide_id left join application_methods am on am.id = a.application_method_id left join units au on au.id = a.application_unit_id left join habitats hb on hb.id = a.habitat_id left join addresses ad on ad.id = a.address_id cross join bounds where a.organization_id = $7 and a.deleted_at is null and a.insecticide_id = any($8::uuid[]) and a.application_method_id = any($9::uuid[]) and a.applicator_profile_id = any($10::uuid[]) and a.application_date >= $11 and a.application_date <= $12 and exists ( select 1 from regions rf where rf.id = any($13::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and case when a.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(a.geom) then a.geom else st_collectionextract(st_makevalid(a.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, a.geom) end ) and a.geom && bounds.geom_4326 and st_intersects(a.geom, bounds.geom_4326) order by a.application_date desc, a.created_at desc, a.id limit $14

