with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select sr.source_reduction_date::text as "c0", srm.name as "c1", sr.sources_eliminated_amount as "c2", su.unit_name as "c3", tp.display_name as "c4", hb.habitat_name as "c5", ad.display_name as "c6", sr.lat as "c7", sr.lng as "c8", to_char(sr.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c9", to_char(sr.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c10" from source_reductions sr left join source_reduction_methods srm on srm.id = sr.source_reduction_method_id left join units su on su.id = sr.sources_eliminated_unit_id left join profiles tp on tp.id = sr.technician_profile_id left join habitats hb on hb.id = sr.habitat_id left join addresses ad on ad.id = sr.address_id cross join bounds where sr.organization_id = $7 and sr.deleted_at is null and sr.source_reduction_method_id = any($8::uuid[]) and sr.technician_profile_id = any($9::uuid[]) and sr.source_reduction_date >= $10 and sr.source_reduction_date <= $11 and exists ( select 1 from regions rf where rf.id = any($12::uuid[]) and rf.organization_id = sr.organization_id and rf.deleted_at is null and rf.geom && sr.geom and case when sr.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(sr.geom) then sr.geom else st_collectionextract(st_makevalid(sr.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, sr.geom) end ) and sr.geom && bounds.geom_4326 and st_intersects(sr.geom, bounds.geom_4326) order by sr.source_reduction_date desc, sr.created_at desc, sr.id limit $13

