with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select ba.biocontrol_date::text as "c0", bm.name as "c1", ba.amount_released as "c2", bu.unit_name as "c3", tp.display_name as "c4", hb.habitat_name as "c5", ad.display_name as "c6", ba.lat as "c7", ba.lng as "c8", to_char(ba.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c9", to_char(ba.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c10" from biocontrol_actions ba left join biocontrol_methods bm on bm.id = ba.biocontrol_method_id left join units bu on bu.id = ba.release_unit_id left join profiles tp on tp.id = ba.technician_profile_id left join habitats hb on hb.id = ba.habitat_id left join addresses ad on ad.id = ba.address_id cross join bounds where ba.organization_id = $7 and ba.deleted_at is null and ba.biocontrol_method_id = any($8::uuid[]) and ba.technician_profile_id = any($9::uuid[]) and ba.habitat_id is not null and ba.biocontrol_date >= $10 and ba.biocontrol_date <= $11 and exists ( select 1 from regions rf where rf.id = any($12::uuid[]) and rf.organization_id = ba.organization_id and rf.deleted_at is null and rf.geom && ba.geom and case when ba.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(ba.geom) then ba.geom else st_collectionextract(st_makevalid(ba.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, ba.geom) end ) and ba.geom && bounds.geom_4326 and st_intersects(ba.geom, bounds.geom_4326) order by ba.biocontrol_date desc, ba.created_at desc, ba.id limit $13

