with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select oa.outreach_date::text as "c0", om.name as "c1", oa.reach as "c2", oa.reach_description as "c3", tp.display_name as "c4", ad.display_name as "c5", oa.lat as "c6", oa.lng as "c7", to_char(oa.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c8", to_char(oa.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c9" from outreach_actions oa left join outreach_methods om on om.id = oa.outreach_method_id left join profiles tp on tp.id = oa.technician_profile_id left join addresses ad on ad.id = oa.address_id cross join bounds where oa.organization_id = $7 and oa.deleted_at is null and oa.outreach_method_id = any($8::uuid[]) and oa.technician_profile_id = any($9::uuid[]) and oa.outreach_date >= $10 and oa.outreach_date <= $11 and exists ( select 1 from regions rf where rf.id = any($12::uuid[]) and rf.organization_id = oa.organization_id and rf.deleted_at is null and rf.geom && oa.geom and case when oa.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(oa.geom) then oa.geom else st_collectionextract(st_makevalid(oa.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, oa.geom) end ) and oa.geom && bounds.geom_4326 and st_intersects(oa.geom, bounds.geom_4326) order by oa.outreach_date desc, oa.created_at desc, oa.id limit $13

-- address export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from addresses a cross join bounds where a.organization_id = $5 and a.deleted_at is null and position(lower($6) in lower(concat_ws(' ', a.display_name, a.address_line_1, a.locality, a.region, a.postal_code))) > 0 and exists ( select 1 from regions rf where rf.id = any($7::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and case when a.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(a.geom) then a.geom else st_collectionextract(st_makevalid(a.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, a.geom) end ) and a.geom && bounds.geom_4326 and st_intersects(a.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select a.display_name as "c0", a.address_line_1 as "c1", a.address_line_2 as "c2", a.locality as "c3", a.region as "c4", a.postal_code as "c5", a.country as "c6", a.lat as "c7", a.lng as "c8", to_char(a.created_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c9", to_char(a.updated_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c10" from addresses a cross join bounds where a.organization_id = $7 and a.deleted_at is null and position(lower($8) in lower(concat_ws(' ', a.display_name, a.address_line_1, a.locality, a.region, a.postal_code))) > 0 and exists ( select 1 from regions rf where rf.id = any($9::uuid[]) and rf.organization_id = a.organization_id and rf.deleted_at is null and rf.geom && a.geom and case when a.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(a.geom) then a.geom else st_collectionextract(st_makevalid(a.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, a.geom) end ) and a.geom && bounds.geom_4326 and st_intersects(a.geom, bounds.geom_4326) order by a.display_name collate natural_sort asc, a.id limit $10

-- service request export
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select count(*)::int as "total" from service_requests sr cross join bounds where sr.organization_id = $5 and sr.deleted_at is null and sr.closed_at is not null and exists ( select 1 from tag_items ti where ti.entity_type = 'service_request' and ti.entity_id = sr.id and ti.deleted_at is null and ti.tag_id = any($6::uuid[]) ) and exists ( select 1 from regions rf where rf.id = any($7::uuid[]) and rf.organization_id = sr.organization_id and rf.deleted_at is null and rf.geom && sr.geom and case when sr.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(sr.geom) then sr.geom else st_collectionextract(st_makevalid(sr.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, sr.geom) end ) and ( position(lower($8) in lower(coalesce('#' || sr.display_name::text, ''))) > 0 or position(lower($9) in lower(sr.details)) > 0 ) and sr.geom && bounds.geom_4326 and st_intersects(sr.geom, bounds.geom_4326)
with bounds as ( select st_makeenvelope( $1, $2, $3, $4, 4326 ) as geom_4326 ) select sr.display_name as "c0", to_char(sr.request_date, 'YYYY-MM-DD') as "c1", case when sr.closed_at is null then 'Open' else 'Closed' end as "c2", (upper(left(replace(sr.intake_type::text, '_', ' '), 1)) || substr(replace(sr.intake_type::text, '_', ' '), 2)) as "c3", ct.contact_name as "c4", ct.preferred_phone as "c5", ct.email as "c6", ad.display_name as "c7", sr.details as "c8", ( select string_agg(tg.tag_name, ', ' order by tg.tag_name) from tag_items ti join tags tg on tg.id = ti.tag_id where ti.entity_type = 'service_request' and ti.entity_id = sr.id and ti.deleted_at is null and tg.deleted_at is null ) as "c9", received_by.display_name as "c10", to_char(sr.closed_at at time zone $5, 'YYYY-MM-DD HH24:MI') as "c11", closed_by.display_name as "c12", sr.lat as "c13", sr.lng as "c14", to_char(sr.created_at at time zone $6, 'YYYY-MM-DD HH24:MI') as "c15", to_char(sr.updated_at at time zone $7, 'YYYY-MM-DD HH24:MI') as "c16" from service_requests sr left join contacts ct on ct.id = sr.contact_id left join addresses ad on ad.id = sr.address_id left join profiles received_by on received_by.id = sr.received_by_profile_id left join profiles closed_by on closed_by.id = sr.closed_by_profile_id cross join bounds where sr.organization_id = $8 and sr.deleted_at is null and sr.closed_at is not null and exists ( select 1 from tag_items ti where ti.entity_type = 'service_request' and ti.entity_id = sr.id and ti.deleted_at is null and ti.tag_id = any($9::uuid[]) ) and exists ( select 1 from regions rf where rf.id = any($10::uuid[]) and rf.organization_id = sr.organization_id and rf.deleted_at is null and rf.geom && sr.geom and case when sr.geom_type in ('st_polygon', 'st_multipolygon') then exists ( select 1 from ( select case when st_isvalid(sr.geom) then sr.geom else st_collectionextract(st_makevalid(sr.geom), 3) end as geom ) record_area where st_relate(rf.geom, record_area.geom, 'T********') and st_area(st_intersection(rf.geom, record_area.geom)) >= 0.001 * least(st_area(rf.geom), st_area(record_area.geom)) ) else st_intersects(rf.geom, sr.geom) end ) and ( position(lower($11) in lower(coalesce('#' || sr.display_name::text, ''))) > 0 or position(lower($12) in lower(sr.details)) > 0 ) and sr.geom && bounds.geom_4326 and st_intersects(sr.geom, bounds.geom_4326) order by sr.request_date asc, sr.created_at asc, sr.id limit $13